<script setup>
import {ref,onMounted} from 'vue';import AppShell from '../components/AppShell.vue';import {supabase} from '../services/supabase';const rows=ref([]),loading=ref(true),error=ref('');async function load(){const {data:{user}}=await supabase.auth.getUser();const {data,error:e}=await supabase.from('applications').select('*, job:jobs!inner(id,title,employer_id), student:profiles!applications_student_id_fkey(full_name,location,bio,course,year_of_study,skills)').eq('job.employer_id',user.id).order('created_at',{ascending:false});rows.value=data||[];error.value=e?.message||'';const fresh=rows.value.filter(a=>a.status==='submitted').map(a=>a.id);if(fresh.length){const {error:updateError}=await supabase.from('applications').update({status:'reviewing'}).in('id',fresh);if(!updateError)rows.value.forEach(a=>{if(fresh.includes(a.id))a.status='reviewing'})}loading.value=false}onMounted(load);async function update(a,status){const {error:e}=await supabase.from('applications').update({status}).eq('id',a.id);if(e)error.value=e.message;else a.status=status}
</script>
<template><AppShell title="Applicants" subtitle="Find your next great team member"><template #default><span class="eyebrow">EMPLOYER WORKSPACE</span><h1 class="page-title">Applicants</h1><p class="page-subtitle">Review applications and keep candidates informed.</p><div v-if="error" class="alert error">{{error}}</div><div v-if="loading" class="empty">Loading applicants…</div><div v-else-if="rows.length" class="grid" style="margin-top:22px"><article v-for="a in rows" :key="a.id" class="card applicant"><div><span class="badge gold">{{a.status}}</span><h3>{{a.student?.full_name||'Student applicant'}}</h3><p class="muted">Applied for <b>{{a.job?.title}}</b> · {{new Date(a.created_at).toLocaleDateString('en-ZA')}}</p><p v-if="a.cover_letter" class="letter">“{{a.cover_letter}}”</p><p v-if="a.student?.bio" class="muted">{{a.student.bio}}</p><p v-if="a.student?.course" class="muted">{{a.student.course}} · {{a.student.year_of_study}}</p><div class="job-meta"><span v-for="skill in (a.student?.skills||[])" :key="skill" class="badge">{{skill}}</span></div></div><div class="actions"><button class="btn btn-primary" :disabled="a.status==='accepted'" @click="update(a,'accepted')">Accept</button><button class="btn btn-outline" :disabled="a.status==='rejected'" @click="update(a,'rejected')">Decline</button><button class="btn btn-outline" @click="update(a,'reviewing')">Mark reviewing</button></div></article></div><div v-else class="empty">No applications received yet. Share your job post to reach more students.</div></template></AppShell></template>
<style scoped>.applicant{display:flex;justify-content:space-between;align-items:center;gap:20px}.applicant h3{margin:12px 0 5px}.applicant p{font-size:13px}.letter{max-width:700px;line-height:1.6}.actions{display:flex;gap:7px;flex-wrap:wrap}@media(max-width:700px){.applicant{align-items:start;flex-direction:column}}</style>
